// Build a short beep as a WAV file in memory (no external file needed)
function makeBeep(freq, seconds) {
  var rate = 8000, n = rate * seconds, buf = new ArrayBuffer(44 + n), v = new DataView(buf);
  function str(o, s) { for (var i = 0; i < s.length; i++) v.setUint8(o + i, s.charCodeAt(i)); }
  str(0, 'RIFF'); v.setUint32(4, 36 + n, true); str(8, 'WAVE'); str(12, 'fmt ');
  v.setUint32(16, 16, true); v.setUint16(20, 1, true); v.setUint16(22, 1, true);
  v.setUint32(24, rate, true); v.setUint32(28, rate, true); v.setUint16(32, 1, true);
  v.setUint16(34, 8, true); str(36, 'data'); v.setUint32(40, n, true);
  for (var i = 0; i < n; i++) v.setUint8(44 + i, 128 + Math.round(60 * Math.sin(2 * Math.PI * freq * i / rate)));
  return URL.createObjectURL(new Blob([buf], { type: 'audio/wav' }));
}
document.getElementById('player').src = makeBeep(440, 2);

var v = document.getElementById('v'), out = document.getElementById('out');
['video/mp4', 'video/webm', 'video/ogg'].forEach(function (t) {
  var li = document.createElement('li');
  li.textContent = t + ' -> ' + (v.canPlayType(t) || 'no');
  out.appendChild(li);
});
